-- OUTER ROLLBACK IS PROVIDED BY THE RUNNER. Synthetic rows only.
SET LOCAL TimeZone='UTC';
CREATE SCHEMA price_test;
GRANT USAGE ON SCHEMA price_test TO anon,authenticated,service_role;
CREATE FUNCTION price_test.ok(value boolean,label text) RETURNS void LANGUAGE plpgsql AS $t$
BEGIN IF value IS DISTINCT FROM true THEN RAISE EXCEPTION 'PRICE_CORE_ASSERT_FAILED: %',label; END IF;
RAISE NOTICE 'PRICE_CORE_PASS: %',label; END $t$;
CREATE FUNCTION price_test.error(statement text,expected_code text,label text) RETURNS void LANGUAGE plpgsql AS $t$
DECLARE got text; BEGIN
  BEGIN EXECUTE statement; EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS got=RETURNED_SQLSTATE; END;
  PERFORM price_test.ok(got IS NOT DISTINCT FROM expected_code,label);
END $t$;
CREATE TABLE price_test.snapshots(name text PRIMARY KEY,value jsonb NOT NULL);
GRANT ALL ON price_test.snapshots TO authenticated;

