DO $atomic$ BEGIN
  BEGIN
    UPDATE public.listings SET title='Should roll back' WHERE id=1001;
    PERFORM public.set_my_listing_price_core_v1('1001','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','0','{"kind":"fixed","amount":"1","currency":"EUR"}'::jsonb);
    RAISE EXCEPTION 'unexpected_success';
  EXCEPTION WHEN SQLSTATE '40001' THEN NULL;
  END;
END $atomic$;
